      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "Ambari HA Setup",
      "activity_description": "Update the Ambari installed Spring XD cluster to spin-up multiple instances of XD-Admin servers, configuring them for High Availability.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "Annotation-Driven Module Model",
      "activity_description": "Create an annotation (@EnableModule) driven programming model for modules, including @Input and @Output annotations, so the application is responsible for creating channel beans and adapters.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "Kryo Optimization & Documentation",
      "activity_description": "Complete the remaining Kryo optimization changes, polish the implementation, and document the guidelines appropriately.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Move CI to EC2",
      "activity_description": "Move the 1.2.x branch to EC2 infrastructure to reliably run CI test suites.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "Maven Repo Module Installation",
      "activity_description": "Brainstorm, investigate, and implement techniques for installing XD modules from a maven repo, allowing the module artifactId to be defined from CLI to download and install to a running Spring XD runtime.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A7",
      "activity_name": "Move Serialization Codec to SI",
      "activity_description": "Move the 'serialization codec' from the Spring XD repo into Spring Integration (SI), and update Spring XD to inherit the features/functionalities via maven dependency.",
