    },
    {
      "activity_id": "A8",
      "activity_name": "CloudController XD Admin SPI",
      "activity_description": "Implement a CloudController based implementation of XD Admin SPI (based on ModuleLauncher) to run data pipeline use-cases on Cloud Foundry, referencing previous spike deliverables.",
